// Plain const data classes for the network payload, config-default, stress
// and tag manifests. The data itself lives in the *.g.dart files generated by
// tool/extract_network_config.dart.

/// Wire direction of a payload.
enum NetDirection { serverbound, clientbound }

/// Wire type of one payload field (derived from the Java StreamCodec).
enum NetKind {
  /// `ByteBufCodecs.VAR_INT` (also ids from idMapper / registries).
  varint,

  /// `ByteBufCodecs.VAR_LONG`.
  varlong,

  /// 4 byte big endian int.
  int,

  /// 8 byte big endian long.
  long,

  /// 2 byte short.
  short,

  /// 1 byte.
  byte,

  /// 1 byte boolean.
  bool,

  /// 4 byte float.
  float,

  /// 8 byte double.
  double,

  /// UTF-8 string, `maxLength` set when the codec bounds it.
  string,

  /// `BlockPos.STREAM_CODEC` (packed long).
  blockPos,

  /// 16 bytes (two longs).
  uuid,

  /// `Identifier` / `ResourceLocation` (string).
  resourceLocation,

  /// `ItemStack.STREAM_CODEC` (non-optional, count > 0).
  itemStack,

  /// `ItemStack.OPTIONAL_STREAM_CODEC` (may be empty).
  itemStackOptional,

  /// `FluidStack.STREAM_CODEC`.
  fluidStack,

  /// `FluidStack.OPTIONAL_STREAM_CODEC`.
  fluidStackOptional,

  /// A block state encoded as its id in `Block.BLOCK_STATE_REGISTRY` (varint).
  blockState,

  /// `ByteBufCodecs.COMPOUND_TAG`.
  nbtCompound,

  /// Any NBT tag (`ByteBufCodecs.TAG`).
  nbtTag,

  /// `ComponentSerialization.STREAM_CODEC`.
  component,

  /// `ByteBufCodecs.byteArray(max)` (varint length + bytes).
  bytes,

  /// `element` repeated, varint count prefix (list, collection, vector, array).
  list,

  /// `key` -> `value`, varint count prefix.
  map,

  /// bool + element (`ByteBufCodecs.optional` and `FriendlyByteBuf.writeNullable`).
  optional,

  /// bool(isLeft) then `key` (left) or `value` (right).
  either,

  /// Enum written as its varint ordinal (`CatnipStreamCodecBuilders.ofEnum`),
  /// `className` is the Java enum.
  enumeration,

  /// 3 doubles.
  vec3,

  /// 3 ints.
  vec3i,

  /// `Direction.STREAM_CODEC` (varint 3d data value).
  direction,

  /// Nested composite codec of `className`; `fields` holds the expansion
  /// (null when the codec could not be expanded).
  custom,

  /// Varint ordinal of the enum `className`, then a variant payload; the
  /// variants are listed in `fields` (name = enum constant).
  dispatch,
}

/// One wire type. Const so the generated manifests can be `const`.
class NetType {
  const NetType(
    this.kind, {
    this.element,
    this.key,
    this.value,
    this.className,
    this.fields,
    this.maxLength,
    this.nullable = false,
  });

  final NetKind kind;

  /// list / optional element.
  final NetType? element;

  /// map key / either left.
  final NetType? key;

  /// map value / either right.
  final NetType? value;

  /// Java type name (enum, custom, dispatch; also set as hint on leaves).
  final String? className;

  /// Expansion of a `custom` composite, or the variants of a `dispatch`.
  final List<NetField>? fields;

  /// String / bytes / list bound where the codec declares one.
  final int? maxLength;

  /// True when the Java value may be null (optional written via nullable()).
  final bool nullable;
}

/// A named, ordered field of a payload (or of an expanded custom type).
class NetField {
  const NetField(this.name, this.type);
  final String name;
  final NetType type;
}

/// One network payload.
class NetPayload {
  const NetPayload({
    required this.id,
    required this.direction,
    required this.javaClass,
    required this.javaSource,
    required this.fields,
    required this.verified,
    this.constant,
    this.note,
  });

  /// `namespace:path` payload type id.
  final String id;
  final NetDirection direction;

  /// Java class (nested classes dotted, e.g. `TrainEditPacket.Serverbound`).
  final String javaClass;

  /// Source path relative to the Create repo (or `catnip:` / `ponder:` jar).
  final String javaSource;

  /// Complete ordered wire field list (superclass fields included).
  final List<NetField> fields;

  /// False when the codec could not be decoded precisely.
  final bool verified;

  /// `AllPackets` enum constant name, when applicable.
  final String? constant;
  final String? note;
}

// ---------------------------------------------------------------- config

enum ConfigSide { client, common, server }

enum ConfigValueType { boolean, integer, decimal, string, enumeration }

/// One config key with its default.
class ConfigEntry {
  const ConfigEntry({
    required this.side,
    required this.path,
    required this.type,
    required this.defaultValue,
    required this.javaClass,
    required this.javaField,
    this.min,
    this.max,
    this.enumClass,
    this.enumValues,
    this.comment = const [],
  });

  final ConfigSide side;

  /// Full TOML path inside the config file, dotted (without the file).
  final String path;
  final ConfigValueType type;

  /// bool / int / double / String (enum constant name for enumerations).
  final Object defaultValue;
  final num? min;
  final num? max;
  final String? enumClass;
  final List<String>? enumValues;

  /// Declaring config class (`CKinetics`) and the Java field name.
  final String javaClass;
  final String javaField;

  /// Comment lines as written in the source (excluding the leading ".").
  final List<String> comment;
}

/// Default stress numbers of one block (key = block path in the create namespace).
class StressEntry {
  const StressEntry(this.block, {this.impact, this.capacity, this.generatedRpm, this.mayGenerateLess});

  final String block;

  /// Stress impact per RPM (`CStress.setImpact`; 0 for `setNoImpact`).
  final double? impact;

  /// Stress capacity per RPM (`CStress.setCapacity`).
  final double? capacity;

  /// `BlockStressValues.setGeneratorSpeed` RPM (tooltips only).
  final int? generatedRpm;
  final bool? mayGenerateLess;
}

// ------------------------------------------------------------------ tags

class TagEntry {
  const TagEntry(this.id, {this.isTag = false, this.required = true});

  /// Resource location (without the leading `#`).
  final String id;

  /// True for `#namespace:tag` references.
  final bool isTag;

  /// False for `{"id": ..., "required": false}` entries.
  final bool required;
}

class TagDef {
  const TagDef({
    required this.category,
    required this.id,
    required this.entries,
    this.replace = false,
  });

  /// Registry directory below `tags/` (block, item, fluid, entity_type, damage_type, ...).
  final String category;

  /// `namespace:path` tag id.
  final String id;
  final bool replace;
  final List<TagEntry> entries;
}
